import{ar as n,r as e}from"./chunk-C8q26AQ9.js";import{a as t}from"../index-ghh6WCA4.js";const i="---\ntitle: Getting Started with AI Video Editing\ndate: 2025-01-25\nauthor: Timeline Team\nslug: getting-started-ai-editing\nexcerpt: Learn how to use AI tools in Timeline Studio to speed up your video editing workflow and create professional content faster.\ncategory: Tutorial\nreadTime: 8 min read\n---\n\n# Getting Started with AI Video Editing\n\nAI is transforming how we edit videos. With Timeline Studio's 151 AI tools, you can automate repetitive tasks and focus on creativity.\n\n## Understanding AI Tools\n\nTimeline Studio integrates with multiple AI providers:\n\n- **Claude (Anthropic)** - Advanced reasoning and creative tasks\n- **OpenAI GPT-4** - General purpose AI assistance\n- **DeepSeek** - Specialized reasoning models\n- **Ollama** - Local models for offline work\n\n## Common AI Workflows\n\n### 1. Smart Montage Planning\nLet AI analyze your footage and suggest the best cuts, transitions, and pacing.\n\n### 2. Automatic Scene Detection\nAI identifies scene changes, key moments, and creates edit points automatically.\n\n### 3. Content-Aware Cropping\nAutomatically reframe videos for different aspect ratios while keeping important subjects in frame.\n\n## Tips for Best Results\n\n1. **Provide Clear Instructions** - The more specific you are, the better results you'll get\n2. **Review AI Suggestions** - AI is a tool to assist, not replace your creative vision\n3. **Experiment with Different Models** - Each AI provider has strengths for different tasks\n\nStart exploring AI features today and transform your editing workflow!",o='---\ntitle: "Timeline Studio Alpha v0.60.0: Professional Video Editor with Free Local AI"\ndate: "2025-08-03"\nauthor: "Timeline Team"\nslug: "alpha-release-ollama-integration"\nexcerpt: "First public alpha release of Timeline Studio with revolutionary AI approach: everything works locally and for free via Ollama!"\ncategory: "Product Launch"\nreadTime: "7 min read"\n---\n\n# Timeline Studio Alpha v0.60.0: Professional Video Editor with Free Local AI\n\n*August 3, 2025*\n\nWe\'re excited to introduce the first public alpha release of Timeline Studio — a professional video editor with a revolutionary approach to AI: **everything works locally and for free!**\n\n## 🚀 Main Feature: 100% Local AI via Ollama\n\nWhile other video editors require expensive cloud AI service subscriptions, Timeline Studio works with **free local Ollama models**:\n\n- **No subscriptions** — use AI as much as you want for free\n- **Complete privacy** — your data stays on your machine\n- **Offline work** — no internet needed after downloading models\n- **Model choice** — Llama 3.2, Phi-3, Gemma 2, Qwen 2.5 and more\n\n### What AI can do in alpha version:\n\n- 📝 **Subtitle generation** — automatic transcription and synchronization\n- 🎬 **Video analysis** — scene and key moment detection\n- 🎯 **Smart hints** — AI helps with editing\n- 🔍 **Content recognition** — frame composition and quality analysis\n\n## 💎 Full-Featured Video Editor for FREE\n\nTimeline Studio isn\'t just "another editor". Even in alpha version you get:\n\n### Core features:\n- ✅ **Multi-track timeline** — unlimited video and audio tracks\n- ✅ **Popular formats** — MP4, MOV, AVI, MKV and more\n- ✅ **Transitions and effects** — basic set for professional work\n- ✅ **Full HD export** — without watermarks!\n- ✅ **GPU acceleration** — fast rendering on supported video cards\n\n### Unique features:\n- 🌍 **15 interface languages** — including Russian, Chinese, Japanese\n- ⚡ **Lightning performance** — thanks to Tauri v2 and optimizations\n- 🔒 **Maximum security** — process isolation, XSS protection\n- 💾 **Local storage** — all data stays on your computer\n\n## 🎯 Our Philosophy: "Free Locally, Paid in Cloud"\n\nWe believe that basic editing tools and AI should be accessible to everyone:\n\n- **Local = Free**: Install Ollama, choose models, work without limits\n- **Cloud = Convenience**: For those who prefer not to configure anything\n\n## 📦 How to Start\n\n### 1. Install Ollama (5 minutes)\n```bash\n# macOS/Linux\ncurl -fsSL https://ollama.com/install.sh | sh\n\n# Windows\n# Download from https://ollama.com/download\n```\n\n### 2. Download AI model (3-5 minutes)\n```bash\n# Recommended model for start\nollama pull llama3.2\n\n# Or lighter version\nollama pull phi3\n```\n\n### 3. Launch Timeline Studio\nJust open the app — it will automatically detect Ollama and available models!\n\n## 🆚 Comparison with Competitors\n\n| Feature | Timeline Studio | Premiere Pro | DaVinci Resolve |\n|---------|----------------|--------------|-----------------|\n| **Price** | FREE | $22.99/month | FREE/Paid |\n| **AI Features** | ✅ Free local | ✅ Paid cloud | ⚠️ Limited |\n| **Languages** | 15 | 20+ | 10 |\n| **GPU Support** | ✅ | ✅ | ✅ |\n| **4K Export** | ✅ | ✅ | ✅ |\n| **Watermarks** | ❌ Never | ❌ | ❌ |\n| **Offline Work** | ✅ Complete | ⚠️ Limited | ✅ |\n\n## 🚧 Alpha Version Limitations\n\nThis is an early version, some things might not work perfectly:\n\n- Some AI models might work slowly on weak computers\n- Export limited to Full HD (4K coming in beta)\n- Some advanced effects still in development\n- Possible bugs and crashes (please report!)\n\n## 🎁 Special Offer for Early Adopters\n\nEveryone who tries the alpha version gets:\n- **Lifetime PRO license** with 50% discount when we launch\n- **Priority support** and direct contact with developers\n- **Influence on development** — your feedback shapes the product\n\n## 📥 Download Now\n\n**Windows** (142 MB)\n[Download for Windows](https://github.com/timeline-studio/releases)\n\n**macOS** (Intel + Apple Silicon) (156 MB)\n[Download for macOS](https://github.com/timeline-studio/releases)\n\n**Linux** (AppImage) (148 MB)\n[Download for Linux](https://github.com/timeline-studio/releases)\n\n## 💬 Community and Support\n\n- **Discord**: [Join our server](https://discord.gg/timeline-studio)\n- **GitHub**: [Report bugs](https://github.com/timeline-studio/timeline-studio)\n- **Email**: support@timelinestudio.pro\n\n## 🔮 What\'s Next?\n\n**Beta version (September 2025):**\n- 4K and 8K export\n- Advanced color correction\n- More AI models\n- Plugin system\n\n**Release v1.0 (December 2025):**\n- Cloud AI integration (optional)\n- Team collaboration\n- Mobile app for remote control\n- Asset marketplace\n\n---\n\n**Try Timeline Studio today and join the revolution of free local AI in video editing!**\n\n*No credit cards, no registrations, no hidden fees. Just download and create.*',a="---\ntitle: Introducing Timeline Studio - AI-Powered Video Editor\ndate: 2025-01-28\nauthor: Chatman Media\nslug: introducing-timeline-studio\nexcerpt: Meet Timeline Studio - a revolutionary video editor that combines professional tools with 151 AI features to transform how you create content.\ncategory: Product Launch\nreadTime: 5 min read\n---\n\n# Introducing Timeline Studio\n\nWe're excited to announce Timeline Studio, a next-generation video editor that brings together the power of AI and professional editing tools in one seamless application.\n\n## Why Timeline Studio?\n\nCreating video content for multiple platforms has never been more challenging. Each platform has its own requirements, formats, and audience expectations. Timeline Studio solves this by offering:\n\n- **One Upload, Multiple Outputs** - Automatically adapt your content for TikTok, YouTube, Instagram, and more\n- **AI-Powered Editing** - 151 specialized AI tools to automate tedious tasks\n- **Professional Quality** - GPU acceleration, 8K rendering, and 60 FPS support\n\n## Key Features\n\n### 🤖 AI Integration\n- Support for Claude, OpenAI, DeepSeek, and Ollama\n- Smart montage planning\n- Automatic scene detection\n- Content-aware editing suggestions\n\n### ⚡ Performance\n- Hardware acceleration with NVENC, QuickSync, VideoToolbox\n- Real-time preview with GPU processing\n- Efficient memory management\n\n### 🌍 Multi-Platform Export\n- Optimized presets for all major platforms\n- Automatic format conversion\n- Direct upload integration\n\n## Get Started\n\nTimeline Studio is available for Windows, macOS, and Linux. Download the latest version and start creating amazing content today!\n\n[Download Timeline Studio →](#download)",r='---\ntitle: "Начало работы с AI видеомонтажом"\ndate: "2025-01-25"\nauthor: "Timeline Team"\nslug: "getting-started-ai-editing"\nexcerpt: "Узнайте, как использовать AI-инструменты в Timeline Studio для ускорения рабочего процесса видеомонтажа и создания профессионального контента быстрее."\ncategory: "Туториал"\nreadTime: "8 мин чтения"\n---\n\n# Начало работы с AI видеомонтажом\n\nДобро пожаловать в будущее видеомонтажа! В этом руководстве мы покажем, как AI-инструменты Timeline Studio могут трансформировать ваш рабочий процесс.\n\n## Настройка AI\n\nПервый шаг - подключение AI-провайдера. Timeline Studio поддерживает несколько вариантов:\n\n### Локальный AI с Ollama (Бесплатно)\n1. Установите Ollama с официального сайта\n2. Загрузите модель: `ollama pull llama3.2`\n3. Timeline Studio автоматически обнаружит локальный AI\n\n### Облачные провайдеры\n- **Claude**: Лучший для креативных задач\n- **OpenAI**: Универсальный выбор\n- **DeepSeek**: Оптимальное соотношение цена/качество\n\n## Основные AI-функции\n\n### 🎬 Автоматическое определение сцен\nAI анализирует ваше видео и автоматически разделяет его на логические сцены. Это экономит часы ручной работы!\n\n### 📝 Генерация субтитров\nПросто нажмите одну кнопку, и AI создаст точные субтитры с правильной синхронизацией.\n\n### 🎯 Умный монтаж\nAI предлагает оптимальные точки монтажа на основе анализа ритма, движения и композиции.\n\n## Практические примеры\n\n### Пример 1: Быстрый монтаж для YouTube\n1. Импортируйте исходное видео\n2. Используйте "AI Анализ" для определения ключевых моментов\n3. Примените "Умную обрезку" для удаления пауз\n4. Экспортируйте с YouTube-пресетом\n\n### Пример 2: Создание короткого видео из длинного\n1. Загрузите длинное видео\n2. Выберите "AI Highlights"\n3. AI найдет самые интересные моменты\n4. Автоматически создаст динамичное короткое видео\n\n## Советы для лучших результатов\n\n- **Качество исходников**: Чем выше качество исходного материала, тем лучше работает AI\n- **Четкие инструкции**: Давайте AI конкретные указания\n- **Проверяйте результаты**: AI - это помощник, финальное решение за вами\n\n## Начните сегодня!\n\nСкачайте Timeline Studio и откройте для себя мощь AI-видеомонтажа. Бесплатная версия включает все базовые AI-функции!',l='---\ntitle: "Timeline Studio Alpha v0.60.0: Полноценный видеоредактор с бесплатным локальным AI"\ndate: "2025-08-03"\nauthor: "Timeline Team"\nslug: "alpha-release-ollama-integration"\nexcerpt: "Первый публичный альфа-релиз Timeline Studio с революционным подходом к AI: всё работает локально и бесплатно через Ollama!"\ncategory: "Product Launch"\nreadTime: "7 min read"\n---\n\n# Timeline Studio Alpha v0.60.0: Полноценный видеоредактор с бесплатным локальным AI\n\n*3 августа 2025*\n\nМы рады представить первый публичный альфа-релиз Timeline Studio — профессионального видеоредактора с революционным подходом к AI: **всё работает локально и бесплатно!**\n\n## 🚀 Главная особенность: 100% локальный AI через Ollama\n\nВ то время как другие видеоредакторы требуют дорогие подписки на облачные AI-сервисы, Timeline Studio работает с **бесплатными локальными моделями Ollama**:\n\n- **Никаких подписок** — используйте AI сколько угодно бесплатно\n- **Полная приватность** — ваши данные никуда не отправляются\n- **Работа офлайн** — не нужен интернет после загрузки моделей\n- **Выбор моделей** — Llama 3.2, Phi-3, Gemma 2, Qwen 2.5 и другие\n\n### Что умеет AI в альфа-версии:\n\n- 📝 **Генерация субтитров** — автоматическая транскрипция и синхронизация\n- 🎬 **Анализ видео** — определение сцен и ключевых моментов\n- 🎯 **Smart подсказки** — AI помогает с монтажом\n- 🔍 **Распознавание контента** — анализ композиции и качества кадров\n\n## 💎 Полноценный видеоредактор БЕСПЛАТНО\n\nTimeline Studio — это не просто "ещё один редактор". Даже в альфа-версии доступны:\n\n### Основные возможности:\n- ✅ **Многодорожечный таймлайн** — неограниченное количество видео и аудио дорожек\n- ✅ **Популярные форматы** — MP4, MOV, AVI, MKV и другие\n- ✅ **Переходы и эффекты** — базовый набор для профессиональной работы\n- ✅ **Экспорт в Full HD** — без водяных знаков!\n- ✅ **GPU-ускорение** — быстрый рендеринг на поддерживаемых видеокартах\n\n### Уникальные фичи:\n- 🌍 **15 языков интерфейса** — включая русский, китайский, японский\n- ⚡ **Молниеносная производительность** — благодаря Tauri v2 и оптимизациям\n- 🔒 **Максимальная безопасность** — изоляция процессов, защита от XSS\n- 💾 **Локальное хранение** — все данные остаются на вашем компьютере\n\n## 🎯 Наша философия: "Локально бесплатно, облачно платно"\n\nМы верим, что базовые инструменты монтажа и AI должны быть доступны каждому:\n\n- **Всё, что работает на вашем компьютере — БЕСПЛАТНО навсегда**\n- **151 AI-инструмент** будет доступен в финальной версии без подписки\n- **Профессиональный Fairlight Audio** — полноценная работа со звуком\n- **Smart Montage Planner** — AI соберёт видео автоматически\n\nПлатные функции появятся только для облачных сервисов:\n- Облачный рендеринг для экономии времени\n- Премиум AI-модели (Claude, GPT-4) для сложных задач\n- Командная работа и синхронизация проектов\n- Stock-библиотеки в 4K/8K качестве\n\n## 📊 Сравнение с конкурентами\n\n| Функция | Timeline Studio FREE | DaVinci Resolve | Premiere Pro | Final Cut Pro |\n|---------|---------------------|-----------------|--------------|---------------|\n| **Цена** | **$0** | $295 | $23/месяц | $299 |\n| **AI инструменты** | **151** (в финальной версии) | 15 | 25 | 10 |\n| **Локальный AI** | **Да (Ollama)** | Нет | Нет | Нет |\n| **Водяной знак** | **Нет** | Нет (в Studio) | Нет | Нет |\n| **Open Source** | **Да** | Нет | Нет | Нет |\n\n## 🔧 Как начать работу\n\n### 1. Установите Ollama (2 минуты)\n```bash\n# macOS\nbrew install ollama\n\n# Linux  \ncurl -fsSL https://ollama.ai/install.sh | sh\n\n# Windows\n# Скачайте с https://ollama.ai/download/windows\n```\n\n### 2. Загрузите AI-модель (5 минут)\n```bash\n# Рекомендуемая лёгкая модель (1.6GB)\nollama pull gemma2:2b\n\n# Запустите сервер\nollama serve\n```\n\n### 3. Скачайте Timeline Studio\n- [Windows (142 MB)](https://github.com/chatman-media/timeline-studio/releases/tag/v0.60.0-alpha)\n- [macOS (156 MB)](https://github.com/chatman-media/timeline-studio/releases/tag/v0.60.0-alpha)\n- [Linux (138 MB)](https://github.com/chatman-media/timeline-studio/releases/tag/v0.60.0-alpha)\n\n## 🧪 Для тестировщиков\n\nЭто альфа-версия, и нам важна ваша обратная связь! Приоритетные области тестирования:\n\n1. **Интеграция с Ollama** — подключение и работа AI\n2. **Базовый монтаж** — импорт, редактирование, экспорт\n3. **Стабильность** — работа без вылетов 30+ минут\n4. **Производительность** — скорость обработки видео\n\n### Известные проблемы альфы:\n- ~1860 TypeScript ошибок (не влияют на работу, исправим в бета)\n- Первый запрос к Ollama медленный (загрузка модели в память)\n- Высокое потребление памяти при больших проектах\n\n## 📅 Дорожная карта\n\n### v0.61.0 (Сентябрь 2025)\n- Интеграция Whisper для улучшенной транскрипции\n- Поддержка больших моделей (7B+)\n- Кэширование результатов AI\n\n### v0.70.0 Beta (Октябрь 2025)\n- Исправление всех TypeScript ошибок\n- Полная функциональность таймлайна\n- Опциональные облачные AI-сервисы\n- Продвинутые эффекты и фильтры\n\n### v1.0.0 Release (Декабрь 2025)\n- Production-ready релиз\n- 151 AI-инструмент локально\n- Smart Montage Planner\n- Fairlight Audio\n- Платные Pro-функции для облака\n\n## 🤝 Присоединяйтесь к сообществу\n\n- **GitHub Issues**: [Сообщайте о багах](https://github.com/chatman-media/timeline-studio/issues)\n- **Discord**: [Общайтесь с командой](https://discord.gg/timeline-studio)\n- **Email**: ak.chatman.media@gmail.com\n\n## 💡 Почему это важно\n\nTimeline Studio — это больше, чем просто видеоредактор. Это заявление о том, что профессиональные инструменты должны быть доступны каждому:\n\n- **Без искусственных ограничений** — используйте все функции бесплатно\n- **Без слежки** — ваши проекты остаются приватными\n- **Без vendor lock-in** — открытый исходный код\n- **С уважением к пользователям** — честная модель монетизации\n\nМы строим будущее, где креативность не ограничена размером кошелька, а AI-инструменты доступны всем, у кого есть компьютер.\n\n**Скачайте альфа-версию сегодня и станьте частью революции в видеомонтаже!**\n\n---\n\n*Timeline Studio Team*  \n*Делаем профессиональный видеомонтаж доступным для всех*',s='---\ntitle: "Представляем Timeline Studio - видеоредактор с AI"\ndate: "2025-01-28"\nauthor: "Chatman Media"\nslug: "introducing-timeline-studio"\nexcerpt: "Знакомьтесь с Timeline Studio - революционный видеоредактор, который объединяет профессиональные инструменты и 151 AI-функцию для трансформации создания контента."\ncategory: "Запуск продукта"\nreadTime: "5 мин чтения"\n---\n\n# Представляем Timeline Studio\n\nМы рады представить Timeline Studio - видеоредактор нового поколения, который объединяет мощь AI и профессиональные инструменты редактирования в одном бесшовном приложении.\n\n## Почему Timeline Studio?\n\nСоздание видеоконтента для множества платформ никогда не было таким сложным. Каждая платформа имеет свои требования, форматы и ожидания аудитории. Timeline Studio решает эту проблему, предлагая:\n\n- **Одна загрузка, множество выходов** - автоматически адаптируйте контент для TikTok, YouTube, Instagram и других платформ\n- **AI-редактирование** - 151 специализированный AI-инструмент для автоматизации рутинных задач\n- **Профессиональное качество** - GPU-ускорение, 8K рендеринг и поддержка 60 FPS\n\n## Ключевые возможности\n\n### 🤖 AI интеграция\n- Поддержка Claude, OpenAI, DeepSeek и Ollama\n- Умное планирование монтажа\n- Автоматическое определение сцен\n- AI-подсказки для редактирования\n\n### ⚡ Производительность\n- Аппаратное ускорение с NVENC, QuickSync, VideoToolbox\n- Предпросмотр в реальном времени с GPU-обработкой\n- Эффективное управление памятью\n\n### 🌍 Мультиплатформенный экспорт\n- Оптимизированные пресеты для всех основных платформ\n- Автоматическая конвертация форматов\n- Прямая интеграция с загрузкой\n\n## Начните прямо сейчас\n\nTimeline Studio доступен для Windows, macOS и Linux. Скачайте последнюю версию и начните создавать потрясающий контент уже сегодня!',d={en:{"introducing-timeline-studio":a,"ai-video-editing-guide":i,"alpha-release-ollama-integration":o,"getting-started-ai-editing":i},ru:{"introducing-timeline-studio":s,"ai-video-editing-guide":r,"alpha-release-ollama-integration":l,"getting-started-ai-editing":r}},u={en:[o,a,i],ru:[l,s,r]};function m(e){const{data:t,content:i}=n(e);return{metadata:{title:t.title||"Untitled",date:t.date||(new Date).toISOString(),author:t.author,slug:t.slug||"",excerpt:t.excerpt,version:t.version,category:t.category,readTime:t.readTime},content:i}}function c(){const{language:n}=t(),[i,o]=e.useState([]),[a,r]=e.useState(!0);return e.useEffect(()=>{!async function(){try{const e=u[n]||u.en,t=[];for(const n of e){const{metadata:e}=m(n);e.slug||(e.slug=e.title.toLowerCase().replace(/\s+/g,"-").replace(/[^a-z0-9-]/g,"")),t.push(e)}t.sort((n,e)=>new Date(e.date).getTime()-new Date(n.date).getTime()),o(t)}catch(e){}finally{r(!1)}}()},[n]),{posts:i,isLoading:a}}function p(n){const{language:i}=t(),[o,a]=e.useState(null),[r,l]=e.useState(!0);return e.useEffect(()=>{!async function(){try{const e=(d[i]||d.en)[n];if(e){const n=m(e);a(n)}}catch(e){}finally{l(!1)}}()},[n,i]),{post:o,isLoading:r}}export{p as a,c as u};
